// Integrity of assets/tools/constellations.js (generated by scripts/make-constellations.mjs): 88 constellations with
// closed J2000 boundary rings, complete names in six languages (Azerbaijani checked against the authoritative table),
// Simplified Chinese, zodiac and classic flags, stick figures that reference known stars, and a cross-check of the
// simplified polygons against the dense IAU boundary points in tests/data/constellations/bound_in_20.txt.
import assert from "node:assert/strict";
import { readFileSync, statSync } from "node:fs";
import { createRequire } from "node:module";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

const require = createRequire(import.meta.url);
const root = fileURLToPath(new URL("..", import.meta.url));
globalThis.window = globalThis.window ?? {};
require("../assets/tools/constellations.js");
const data = window.AstroNotConstellations;
const { constellations, stars } = data;
const zodiac = require("../tools/public-zodiac.js");
const extra = JSON.parse(readFileSync(root + "scripts/constellations-extra.json", "utf8"));

test("88 constellations, 89 rings, Serpens in two parts, sorted by Latin name", () => {
  assert.equal(constellations.length, 88);
  assert.equal(constellations.reduce((n, c) => n + c.polygons.length, 0), 89);
  assert.equal(constellations.find((c) => c.desig === "Ser").polygons.length, 2);
  const names = constellations.map((c) => c.name);
  assert.deepEqual(names, names.slice().sort((a, b) => a.localeCompare(b, "en")));
  assert.equal(new Set(constellations.map((c) => c.desig)).size, 88);
});

test("names are complete in six languages, az equals the authoritative table, en is the Latin name", () => {
  for (const c of constellations) {
    for (const code of ["en", "az", "tr", "ru", "zh", "es"]) assert.ok(c.names[code] && c.names[code].trim(), c.desig + " " + code);
    assert.equal(c.names.en, c.name);
    assert.equal(c.names.az, extra.az[c.desig], c.desig);
  }
  assert.equal(Object.keys(extra.az).length, 88);
  const byDesig = Object.fromEntries(constellations.map((c) => [c.desig, c.names]));
  assert.equal(byDesig.Cas.tr, "Kraliçe");
  assert.equal(byDesig.Sco.es, "Escorpio");
  assert.equal(byDesig.Cyg.az, "Qu quşu");
  assert.equal(byDesig.Oph.az, "İlanbürc");
  assert.equal(byDesig.UMa.zh, "大熊座");
  assert.equal(byDesig.Ori.zh, "猎户座");
});

test("zh names are Simplified Chinese", () => {
  const traditional = /[寶雙鵝魚飛龍鳥馬獅貓鶴鷹蠍鯨劍時顯鏡繪盤網羅雲爐圓規鳳鴿烏龜獵戶髮壇鐘長蒼蠅極鵑處遠儀]/;
  for (const c of constellations) assert.ok(!traditional.test(c.names.zh), c.desig + " " + c.names.zh);
});

test("rings are closed with RA in [0, 360) and Dec in [-90, 90]; labels lie inside their constellation", () => {
  for (const c of constellations) {
    for (const ring of c.polygons) {
      assert.ok(ring.length >= 4, c.desig);
      assert.deepEqual(ring[0], ring[ring.length - 1], c.desig + " ring not closed");
      for (const [ra, dec] of ring) assert.ok(ra >= 0 && ra < 360 && dec >= -90 && dec <= 90, c.desig);
    }
    assert.equal(zodiac.pointInConstellation(c.label[0], c.label[1], constellations), c.desig, "label of " + c.desig);
  }
});

test("zodiac order, classic flags, stick figures and star references", () => {
  const withZodiac = constellations.filter((c) => c.zodiac).sort((a, b) => a.zodiac - b.zodiac);
  assert.deepEqual(withZodiac.map((c) => c.desig), ["Ari", "Tau", "Gem", "Cnc", "Leo", "Vir", "Lib", "Sco", "Sgr", "Cap", "Aqr", "Psc", "Oph"]);
  assert.deepEqual(constellations.filter((c) => c.classic).map((c) => c.desig).sort(), ["Cas", "Cru", "Cyg", "Ori", "Sco", "UMa"]);
  const withLines = constellations.filter((c) => c.lines);
  assert.equal(withLines.length, 18);
  for (const c of withLines) {
    assert.ok(c.anchor && c.lines.flat().includes(c.anchor), c.desig + " anchor");
    for (const name of c.lines.flat()) {
      assert.ok(Array.isArray(stars[name]) && stars[name].length === 3, c.desig + " star " + name);
      assert.equal(zodiac.pointInConstellation(stars[name][0], stars[name][1], constellations), c.desig, name + " should lie in " + c.desig);
    }
  }
  assert.equal(constellations.filter((c) => !c.lines).every((c) => c.anchor === null), true);
});

test("dense IAU boundary cross-check: within 0.05° in the zodiac and 0.5° elsewhere", () => {
  const dense = readFileSync(root + "tests/data/constellations/bound_in_20.txt", "utf8").trim().split(/\r?\n/);
  const byDesig = new Map(constellations.map((c) => [c.desig.toUpperCase(), c]));
  // bound_in_20 names Serpens parts SER1/SER2 and uses upper case.
  const worst = { zodiac: 0, other: 0 };
  let checked = 0;
  for (const line of dense) {
    const [hours, decText, code] = line.trim().split(/\s+/);
    const constellation = byDesig.get(code.replace(/\d$/, ""));
    assert.ok(constellation, "unknown code " + code);
    const ra = Number(hours) * 15;
    const dec = Number(decText);
    const distance = zodiac.boundaryDistance(ra, dec, constellation);
    const group = constellation.zodiac ? "zodiac" : "other";
    worst[group] = Math.max(worst[group], distance);
    checked++;
  }
  assert.ok(checked > 13_000, "dense points " + checked);
  assert.ok(worst.zodiac <= 0.05, "zodiac deviation " + worst.zodiac);
  assert.ok(worst.other <= 0.5, "other deviation " + worst.other);
});

test("the asset stays small and names its sources", () => {
  assert.ok(statSync(root + "assets/tools/constellations.js").size < 150_000);
  assert.match(data.source.licence, /BSD-3-Clause/);
  assert.match(data.source.fetched, /^\d{4}-\d{2}-\d{2}$/);
});
